// This file is generated by AI.

// 配音队列的调度规则 (纯函数)。
//
// 抽成独立模块的原因: 这些规则是功能的正确性核心 (串行、立即优先、按角色分组),
// 但控制器本身依赖 Tauri 与 DOM, 无法直接单测。这里只描述"顺序", 不做任何副作用。
//
// 规则:
// 1. **立即队列整体优先于普通队列**。测试任务进立即队列, 生成任务进普通队列;
// 2. 每个队列内部**按角色分组**: 同一角色的任务连续执行, 避免服务端反复重载模型
//    (切换权重需要重载底模并合并 LoRA, 代价很高);
// 3. 分组按**首次出现的顺序**排列, 不做跨组归并 —— 否则立即任务会被普通任务拖住。

export type TaskKind = 'test' | 'generate';
export type TaskStatus = 'pending' | 'running' | 'done' | 'failed' | 'canceled';

/** 调度所需的最小任务描述 */
export interface QueueTask {
  id: string;
  kind: TaskKind;
  status: TaskStatus;
  /** 角色 id; null 表示尚未指定角色 */
  characterId: string | null;
}

/** 同角色的连续任务组 */
export interface TaskGroup<T> {
  characterId: string | null;
  tasks: T[];
}

/**
 * 按角色把任务分组, 保持首次出现顺序。
 *
 * 注意: `characterId` 为 `null` 的任务会被归入同一组 (键为空串),
 * 与"未指定角色"的任务一起连续执行。
 */
export function groupByCharacter<T extends QueueTask>(tasks: T[]): TaskGroup<T>[] {
  const groups = new Map<string, TaskGroup<T>>();
  for (const task of tasks) {
    const key = task.characterId ?? '';
    const existing = groups.get(key);
    if (existing) {
      existing.tasks.push(task);
    } else {
      groups.set(key, { characterId: task.characterId ?? null, tasks: [task] });
    }
  }
  return [...groups.values()];
}

/** 展开为实际执行顺序: 先立即队列 (测试), 再普通队列 (生成) */
export function executionOrder<T extends QueueTask>(tasks: T[]): T[] {
  const immediate = groupByCharacter(tasks.filter((task) => task.kind === 'test' && task.status === 'pending'));
  const normal = groupByCharacter(tasks.filter((task) => task.kind === 'generate' && task.status === 'pending'));
  return [...immediate, ...normal].flatMap((group) => group.tasks);
}

/** 下一个应当执行的任务; 队列为空时返回 `null` */
export function nextTask<T extends QueueTask>(tasks: T[]): T | null {
  return executionOrder(tasks)[0] ?? null;
}

/** 队列概览 (供 UI 展示) */
export interface QueueSummary {
  pending: number;
  pendingTest: number;
  pendingGenerate: number;
  running: number;
  /** 立即队列将把生成任务延后多久 (毫秒, 由调用方估算后传入) */
  delayMillis: number;
}

/** 统计队列状态 */
export function summarize<T extends QueueTask>(tasks: T[], estimate: (tasks: T[]) => number): QueueSummary {
  const pending = tasks.filter((task) => task.status === 'pending');
  const pendingTest = pending.filter((task) => task.kind === 'test');
  const pendingGenerate = pending.filter((task) => task.kind === 'generate');
  const running = tasks.filter((task) => task.status === 'running');
  return {
    pending: pending.length,
    pendingTest: pendingTest.length,
    pendingGenerate: pendingGenerate.length,
    running: running.length,
    // 立即队列先跑, 因此它对生成任务的延后量 = 立即队列 + 运行中任务的总耗时
    delayMillis: estimate([...running, ...executionOrder(pendingTest)]),
  };
}
